def is_gauge_realizable(cl, universe):
    from itertools import combinations
    subsets = [frozenset()]
    for r in range(1, len(universe)+1):
        for c in combinations(universe, r):
            subsets.append(frozenset(c))
    closed = [s for s in subsets if cl(s) == s]
    for i, s in enumerate(closed):
        for t in closed[i+1:]:
            if not (s <= t or t <= s):
                return False
    return True

def reconstruct_valuation(cl, universe):
    base = len(cl(frozenset()))
    return {x: len(cl(frozenset([x]))) - base for x in universe}

def normalize_valuation(v):
    elements = list(v.keys())
    return {x: sum(1 for y in elements if v[y] < v[x]) for x in elements}
